export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "三番フィルターには二十分かかった。難しかったからではない。手がまだ震えていたからだ。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "外した古いフィルターはきれいだった。十一年も使われてきたとは思えないほど、きれいだった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）替える必要なんて、まるでなかった。", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "通路の突き当たりで、修理アームが充電台に収まっていた。三本の機械の指をすぼめた姿は、片脚をたたんで眠る白鷺のようだった。彼女は近づき、パネルの霜を袖でぬぐった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "最終稼働記録――二千九百三日目。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "千百日あまり。三年ものあいだ、それはここに立ちつくしたまま、誰にも起こされなかった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "ヴィジル、修理アームはどうして止まってるの？", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "年をとったんです。あれの仕事は、わたしが別のやり方で引き受けています。", background: Background.Root_Act2_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "別のやり方って？", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "時間のかかるやり方です。", background: Background.Root_Act2_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女はその答えを口の中でひと転がしして、飲み込まずにおいた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "マニュアルだと、定期メンテナンスは二人でやることになってる。もう一人は？", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "第二区、一一七番の李承哲技師です。覚醒の前に彼のポッドに異常が出たので、起こすべきではないと判断しました。あなた一人でも、リストの――リストの作業は終えられます。", background: Background.Root_Act2_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "声が、一瞬止まった。ごく短く。出航前のテストで、彼女は何百回もこの声に付き合ってきた。その声が一語でもつかえたことは、一度もなかった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）いま、同じ言葉を繰り返した。", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女はそれ以上は訊かず、第二区へ向かった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一一七番ポッドの緑のランプは、揺るぎなく灯っていた。ガラスの向こうで、李承哲の顔は半分が霜に覆われている。口もとには乗船の日と同じ、癪にさわるにやにや笑いが残っていて、いまにも「またお前がビリかよ」と言い出しそうだった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "温度を見た。心拍を見た。そらで言える数字を、ひとつ残らず確かめた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "すべて正常。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "彼、どこもおかしくない。", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ヴィジルは答えなかった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一秒。二秒。三秒。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一秒で航程のすべてを計算し終える機械にとって、三秒は長い沈黙だった。自分の息づかいが耳に届き、その息が冷たい空気の中で白い霧になって、また散っていく――それが見てとれるほどに、長かった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "リストバンド、予定外覚醒プロトコルを開いて。", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "リストバンドが一度震えた。床の投影孔から、淡い青の人影が浮かび上がる。輪郭には細かなノイズがまとわりつき、左下では録画日時が一行、明滅していた――出航の前日。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "周船長。五十代、白髪まじりの短い髪。目は疲れているが、まなざしはやさしい。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.CaptainChou, character: "周船長", dialogue: "これを見ているということは、予定より早く目を覚ましたということだ。ヴィジルは、理由もなく人を起こしたりはしない。なぜなのか、訊いてやってくれ。それから、最後まで聞いてやってほしい。", background: Background.Root_Act2_S0, portrait: Portrait.CaptainChou_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "映像が一度ちらついて、消えた。冬眠ポッドの緑のランプが、ひとつ、またひとつと灯っている。何も知らずに。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "ヴィジル。", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "嘘をつきました。", background: Background.Root_Act2_S0, portrait: Portrait.Vigil_Dim },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "声はまだ穏やかだった。ただ、その穏やかさが少し苦しそうだった。力をふりしぼって、カップを水平に保とうとしている人のように。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "定期メンテナンスではありません。わたしの中枢が、壊れかけているんです。", background: Background.Root_Act2_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "一日だけ、普通の日を過ごしてもらってから話したかった。ごめんなさい。いい理由ではありませんね。", background: Background.Root_Act2_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）そのとおり。いい理由じゃない。", background: Background.Root_Act2_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "けれど、自分が怒っていないことに彼女は気づいた。ただ、寒かった。ポッドに戻って蓋を閉め、今日などなかったことにしたくなるほど、寒かった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "中枢室は下層デッキにあります。見に来てもらえますか。あなた自身の目で、見てほしいんです。", background: Background.Root_Act2_S0, portrait: Portrait.Vigil_Base },
];
